<?php require '../config/database.php';auth();$date=$_GET['date']??date('Y-m-d');$s=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM payments WHERE DATE(created_at)=?');$s->execute([$date]);$payment=$s->fetchColumn();$s=$pdo->prepare('SELECT COALESCE(SUM(paid),0) FROM sales WHERE DATE(created_at)=?');$s->execute([$date]);$sales=$s->fetchColumn();$s=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE DATE(created_at)=?');$s->execute([$date]);$expenses=$s->fetchColumn();$income=$payment+$sales;$net=$income-$expenses;$rep=$pdo->prepare("SELECT COUNT(*) FROM repairs WHERE DATE(created_at)=?");$rep->execute([$date]);$repairCount=$rep->fetchColumn();?><!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><link rel="stylesheet" href="../assets/css/style.css"><main><h1>التقرير المالي اليومي</h1><form method="get"><label>التاريخ</label><input type="date" name="date" value="<?=$date?>"><button>عرض</button></form><div class="cards"><div>دفعات الصيانة<strong><?=number_format($payment,2)?></strong></div><div>مبيعات اليوم<strong><?=number_format($sales,2)?></strong></div><div>إجمالي الدخل<strong><?=number_format($income,2)?></strong></div><div>المصروفات<strong><?=number_format($expenses,2)?></strong></div><div>صافي الدخل<strong><?=number_format($net,2)?></strong></div><div>طلبات الصيانة<strong><?=$repairCount?></strong></div></div></main>
